#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
European economic performance -> data storytelling report builder.

Discovers candidate data files in the current workspace, normalizes numeric
records into (geo, metric, year, value) observations using light heuristics,
derives story facts (trends, rankings, dispersion, cross-metric relations),
and writes a Markdown data-storytelling report artifact.
"""
import csv
import json
import math
import os
import re
from datetime import datetime, timezone

OUT_NAME = "european_economic_performance_story.md"

# ---------------------------------------------------------------------------
# Dictionaries used by the heuristic normalizer
# ---------------------------------------------------------------------------

COUNTRY_ALIASES = {
    "Germany": ["germany", "german", "deu"],
    "France": ["france", "fra"],
    "Italy": ["italy", "ita"],
    "Spain": ["spain", "esp"],
    "Netherlands": ["netherlands", "holland", "nld"],
    "Belgium": ["belgium", "bel"],
    "Austria": ["austria", "aut"],
    "Portugal": ["portugal", "prt"],
    "Greece": ["greece", "grc"],
    "Ireland": ["ireland", "irl"],
    "Finland": ["finland", "fin"],
    "Sweden": ["sweden", "swe"],
    "Denmark": ["denmark", "dnk"],
    "Poland": ["poland", "pol"],
    "Czechia": ["czech republic", "czechia", "czech", "cze"],
    "Slovakia": ["slovakia", "slovak republic", "svk"],
    "Slovenia": ["slovenia", "svn"],
    "Hungary": ["hungary", "hun"],
    "Romania": ["romania", "rou"],
    "Bulgaria": ["bulgaria", "bgr"],
    "Croatia": ["croatia", "hrv"],
    "Estonia": ["estonia", "est"],
    "Latvia": ["latvia", "lva"],
    "Lithuania": ["lithuania", "ltu"],
    "Luxembourg": ["luxembourg", "lux"],
    "Cyprus": ["cyprus", "cyp"],
    "Malta": ["malta", "mlt"],
    "United Kingdom": ["united kingdom", "britain", "uk", "gbr"],
    "United States": ["united states", "usa", "us"],
    "Euro area": ["euro area", "eurozone", "euro area countries", "ea20", "ea19", "ea"],
    "European Union": ["european union", "eu27", "eu 27", "eu"],
    "Europe": ["europe"],
    "Norway": ["norway", "nor"],
    "Switzerland": ["switzerland", "swiss", "che"],
    "Iceland": ["iceland", "isl"],
    "Turkey": ["turkey", "tur"],
}

AGGREGATE_GEOS = {"European Union", "Euro area", "Europe"}

# ordered metric specs: (key, display label, synonym fragments, direction)
METRIC_SPECS = [
    ("gdp_per_capita", "GDP per capita", ["gdppercapita", "percapitagdp", "gdppc"], "higher"),
    ("gdp_growth", "GDP growth", ["gdpgrowth", "gdp growth", "realgdpgrowth",
                                  "economicgrowth", "economygrowth", "real gdp"], "higher"),
    ("inflation", "Inflation (HICP/CPI)", ["inflation", "hicp", "consumerpriceindex",
                                           "cpi"], "lower"),
    ("unemployment", "Unemployment", ["unemployment", "jobless"], "lower"),
    ("deficit", "Government balance / deficit", ["deficit", "budgetbalance",
                                                 "governmentbalance", "fiscalbalance",
                                                 "netlending"], "higher"),
    ("debt", "Government debt", ["governmentdebt", "publicdebt", "debttogdp", "debt"], "lower"),
    ("gdp", "GDP (level)", ["gdp", "grossdomesticproduct"], "higher"),
    ("productivity", "Productivity", ["productivity", "labourproductivity",
                                      "laborproductivity"], "higher"),
    ("exports", "Exports", ["exports", "export"], "higher"),
    ("imports", "Imports", ["imports", "import"], "higher"),
    ("current_account", "Current account", ["currentaccount", "current account"], "higher"),
    ("employment", "Employment", ["employment"], "higher"),
    ("investment", "Investment", ["investment", "grossfixedcapital"], "higher"),
    ("interest_rate", "Interest rate", ["interestrate", "interest rate",
                                        "longterminterest"], "lower"),
    ("consumption", "Consumption", ["consumption"], "higher"),
    ("population", "Population", ["population"], "higher"),
]

METRIC_LABEL = {k: lab for k, lab, _syn, _d in METRIC_SPECS}
METRIC_DIR = {k: d for k, _lab, _syn, d in METRIC_SPECS}
PCT_METRICS = {"gdp_growth", "unemployment", "inflation", "deficit", "interest_rate",
               "employment"}

HERO_PREFERENCE = ["gdp_growth", "unemployment", "inflation", "deficit", "debt",
                   "gdp_per_capita", "gdp", "exports", "imports", "employment",
                   "productivity", "investment", "current_account", "interest_rate",
                   "consumption", "population"]

ALIAS_CANDIDATES = []
for _canon, _aliases in COUNTRY_ALIASES.items():
    for _a in _aliases:
        ALIAS_CANDIDATES.append((_a, _canon))
ALIAS_CANDIDATES.sort(key=lambda t: (len(t[0].split()), len(t[0])), reverse=True)

GEO_WORDS = {"country", "geo", "geography", "area", "region", "member state",
             "economy", "jurisdiction", "nation", "territory", "country/area",
             "country area"}
YEAR_WORDS = {"year", "date", "period", "time", "observation date"}

# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def safe_float(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if math.isnan(f) or math.isinf(f):
        return None
    return f


def words_of(text):
    return re.findall(r"[a-z]+", text.lower())


def nospace_of(words):
    return "".join(words)


def years_of(text):
    return sorted({int(y) for y in re.findall(r"(?<!\d)(?:19|20)\d\d(?!\d)", text)
                   if 1950 <= int(y) <= 2035})


def alias_in_words(words, alias):
    parts = alias.split()
    if not parts:
        return False
    if len(parts) == 1:
        p = parts[0]
        if len(p) <= 3:
            return p in words
        return any((p in w) or (w in p) for w in words)
    for i in range(len(words) - len(parts) + 1):
        if words[i:i + len(parts)] == parts:
            return True
    return False


def metric_from_words(words, weak=False):
    txt = nospace_of(words)
    for key, _lab, syns, _d in METRIC_SPECS:
        for s in syns:
            sn = re.sub(r"[^a-z0-9]", "", s.lower())
            if sn and sn in txt:
                return key
    if weak:
        if "growth" in words:
            return "gdp_growth"
        if "rate" in words and "unemployment" in txt:
            return "unemployment"
    return None


def roles_from_words(words):
    geos = set()
    for alias, canon in ALIAS_CANDIDATES:
        if alias_in_words(words, alias):
            geos.add(canon)
    metric = metric_from_words(words)
    return geos, metric


def slugify(text):
    return re.sub(r"[^a-z0-9]+", "_", str(text).lower()).strip("_") or "value"


def mean(xs):
    xs = [x for x in xs if x is not None]
    return sum(xs) / len(xs) if xs else None


def stdev(xs):
    xs = [x for x in xs if x is not None]
    if len(xs) < 2:
        return None
    m = sum(xs) / len(xs)
    return math.sqrt(sum((x - m) ** 2 for x in xs) / (len(xs) - 1))


def pearson(xs, ys):
    pairs = [(x, y) for x, y in zip(xs, ys) if x is not None and y is not None]
    if len(pairs) < 3:
        return None, 0
    xs = [p[0] for p in pairs]
    ys = [p[1] for p in pairs]
    mx, my = mean(xs), mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return None, len(pairs)
    return num / (dx * dy), len(pairs)


def fmt_val(v, metric):
    if v is None:
        return "n/a"
    if metric in PCT_METRICS:
        return f"{v:,.2f}%"
    if abs(v) >= 1000:
        return f"{v:,.1f}"
    return f"{v:,.2f}"


def md_table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "| " + " | ".join(["---"] * len(headers)) + " |"]
    for r in rows:
        out.append("| " + " | ".join(str(c) for c in r) + " |")
    return "\n".join(out)

# ---------------------------------------------------------------------------
# Discovery / parsing
# ---------------------------------------------------------------------------

def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")
                       and d != "__pycache__"]
        for fn in sorted(filenames):
            ext = os.path.splitext(fn)[1].lower()
            if ext in (".json", ".csv", ".tsv", ".txt", ".md", ".dat", ".data"):
                if fn == OUT_NAME:
                    continue
                found.append(os.path.join(dirpath, fn))
    return sorted(found)


def parse_json_text(text):
    """Return a grid (headers, rows-of-lists) or a nested dict or None."""
    try:
        obj = json.loads(text)
    except Exception:
        return None
    if isinstance(obj, dict):
        return obj
    if isinstance(obj, list):
        if not obj:
            return None
        if all(isinstance(r, dict) for r in obj):
            headers = []
            for r in obj:
                for k in r.keys():
                    if k not in headers:
                        headers.append(k)
            rows = [[r.get(h) for h in headers] for r in obj]
            return (headers, rows)
        if all(isinstance(r, list) for r in obj):
            widths = {len(r) for r in obj}
            if len(widths) == 1 and obj:
                return (list(range(len(obj[0]))), obj)
    return None


def flatten_json(obj, path=()):
    """Yield (path_tokens, scalar) leaves of a JSON dict structure."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from flatten_json(v, path + (str(k),))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            yield from flatten_json(v, path + (str(i),))
    else:
        yield path, obj


def detect_delimiter(text):
    lines = text.splitlines()[:6]
    best, bestn = ",", 0
    for d in [";", "\t", "|", ","]:
        counts = []
        for line in lines:
            if d in line:
                counts.append(len(line.split(d)))
        if counts:
            n = max(counts) - min(counts)
            med = sorted(counts)[len(counts) // 2]
            score = med if n <= 1 else 0
            if score > bestn:
                bestn, best = score, d
    return best


def rows_from_csv_text(text):
    delim = detect_delimiter(text)
    reader = csv.reader(text.splitlines(), delimiter=delim)
    rows = [r for r in reader if r and any(c.strip() for c in r)]
    if not rows:
        return None
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    # skip separator rows like |---|---|
    rows = [r for r in rows if not all(re.fullmatch(r"[\s:\-]+", c) for c in r if c)]
    return rows


def rows_from_pipe_table(text):
    lines = [ln.strip() for ln in text.splitlines() if "|" in ln]
    rows = []
    for ln in lines:
        cells = [c.strip() for c in ln.strip("|").split("|")]
        if len(cells) >= 3:
            rows.append(cells)
    rows = [r for r in rows if not all(re.fullmatch(r"[\s:\-]+", c) for c in r)]
    if len(rows) < 2:
        return None
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    return rows


def parse_text_grid(text, file_words):
    """Return a grid (headers, rows) if the text looks tabular."""
    rows = rows_from_pipe_table(text)
    if rows is None:
        try:
            rows = rows_from_csv_text(text)
        except Exception:
            rows = None
    if rows is None or len(rows) < 2:
        return None
    return (rows[0], rows[1:])


# ---------------------------------------------------------------------------
# Observation building
# ---------------------------------------------------------------------------

def leaf_to_obs(path_tokens, value, fgeos, fmetric):
    raw = " ".join(str(p) for p in path_tokens)
    years = years_of(raw)
    lgeos, lmetric = roles_from_words(words_of(raw))
    if len(lgeos) > 1:
        return None
    if not lgeos and len(fgeos) == 1:
        lgeos = set(fgeos)
    if not lgeos:
        return None
    geo = next(iter(lgeos))
    metric = lmetric or fmetric
    if not years:
        return None
    year = max(years)
    num = safe_float(value)
    if num is None:
        return None
    return (geo, metric or "indicator", year, num)


def grid_obs(headers, rows, fgeos, fmetric):
    """Heuristic conversion of a tabular grid into observations."""
    if not headers or not rows:
        return []
    out = []
    n = len(headers)
    infos = []
    for h in headers:
        hs = str(h).strip()
        low = hs.lower()
        words = words_of(hs)
        geos, metric = roles_from_words(words)
        infos.append({"geo": geos, "metric": metric, "text": hs,
                      "is_geo_word": low in GEO_WORDS,
                      "is_year_word": low in YEAR_WORDS,
                      "is_bare_year": bool(re.fullmatch(r"(?:19|20)\d\d", hs)),
                      "geo_only": len(geos) == 1 and not metric and not infos[-1]["text"].lower() in GEO_WORDS if infos else len(geos) == 1 and not metric})
    # fix geo_only awkwardness by recomputing
    infos = []
    for h in headers:
        hs = str(h).strip()
        low = hs.lower()
        words = words_of(hs)
        geos, metric = roles_from_words(words)
        infos.append({"geo": geos, "metric": metric, "text": hs,
                      "is_geo_word": low in GEO_WORDS,
                      "is_year_word": low in YEAR_WORDS,
                      "is_bare_year": bool(re.fullmatch(r"(?:19|20)\d\d", hs))})

    geo_idx = None
    year_idx = None
    for i, info in enumerate(infos):
        if info["is_geo_word"] and geo_idx is None:
            geo_idx = i
        if info["is_year_word"] and year_idx is None:
            year_idx = i

    # majority-country column fallback for geo
    if geo_idx is None and n:
        best, best_frac = None, 0.0
        for i in range(n):
            vals = [r[i] for r in rows if i < len(r)]
            if not vals:
                continue
            hits = 0
            for v in vals:
                gs, _m = roles_from_words(words_of(str(v)))
                if len(gs) == 1:
                    hits += 1
            frac = hits / len(vals)
            if frac >= 0.6 and frac > best_frac:
                best_frac, best = frac, i
        geo_idx = best

    def geo_from_cell(v):
        gs, _m = roles_from_words(words_of(str(v)))
        if len(gs) == 1:
            return next(iter(gs))
        return None

    def year_from_cell(v):
        ys = years_of(str(v))
        return ys[-1] if ys else None

    def add(geo, metric, year, value):
        num = safe_float(value)
        if geo and num is not None:
            out.append((geo, metric or "indicator", year, num))

    # Tidy long format: one geo column + one year column, others are metrics
    if geo_idx is not None and year_idx is not None:
        for r in rows:
            if year_idx >= len(r) or geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            yr = year_from_cell(r[year_idx])
            if not geo or yr is None:
                continue
            for i, h in enumerate(headers):
                if i in (geo_idx, year_idx) or i >= len(r):
                    continue
                metric = infos[i]["metric"] or slugify(infos[i]["text"])
                add(geo, metric, yr, r[i])
        return out

    # Wide format A: country rows, bare-year columns
    bare_year_cols = [i for i, info in enumerate(infos) if info["is_bare_year"]]
    if geo_idx is not None and bare_year_cols and year_idx is None:
        other_metric_cols = [i for i in range(n)
                             if i not in bare_year_cols and i != geo_idx
                             and infos[i]["metric"]]
        default_metric = fmetric or "indicator"
        for r in rows:
            if geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            if not geo:
                continue
            for ci in bare_year_cols:
                if ci >= len(r):
                    continue
                add(geo, default_metric, int(infos[ci]["text"]), r[ci])
            for ci in other_metric_cols:
                if ci >= len(r):
                    continue
                yr = year_from_cell(r[geo_idx]) if False else None
                add(geo, infos[ci]["metric"], yr, r[ci])
        return out

    # Wide format B: year rows, geo-name columns
    geo_cols = [i for i, info in enumerate(infos) if len(info["geo"]) == 1
                and not info["is_geo_word"] and not info["is_year_word"]
                and not info["is_bare_year"]]
    if year_idx is not None and geo_cols:
        metric = fmetric or "indicator"
        for r in rows:
            if year_idx >= len(r):
                continue
            yr = year_from_cell(r[year_idx])
            if yr is None:
                continue
            for ci in geo_cols:
                if ci >= len(r):
                    continue
                add(next(iter(infos[ci]["geo"])), metric, yr, r[ci])
        return out

    # Rows of countries with metric columns (no year info): snapshot obs
    if geo_idx is not None:
        for r in rows:
            if geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            if not geo:
                continue
            for i, h in enumerate(headers):
                if i == geo_idx or i >= len(r):
                    continue
                metric = infos[i]["metric"] or slugify(infos[i]["text"])
                add(geo, metric, None, r[i])
        return out

    # Time series per metric column with a single geo from filename
    if year_idx is not None and len(fgeos) == 1:
        geo = next(iter(fgeos))
        metric = fmetric or "indicator"
        for r in rows:
            if year_idx >= len(r):
                continue
            yr = year_from_cell(r[year_idx])
            if yr is None:
                continue
            for i, h in enumerate(headers):
                if i == year_idx or i >= len(r):
                    continue
                add(geo, infos[i]["metric"] or metric, yr, r[i])
        return out

    # Last resort: first column numeric looks like years, first row headers metrics
    first_vals = [safe_float(r[0]) for r in rows]
    first_years = [year_from_cell(r[0]) for r in rows]
    if first_years and all(y is not None for y in first_years[:3]) and len(fgeos) == 1:
        geo = next(iter(fgeos))
        for r in rows:
            yr = year_from_cell(r[0])
            if yr is None:
                continue
            for i, h in enumerate(headers):
                if i == 0 or i >= len(r):
                    continue
                add(geo, infos[i]["metric"] or fmetric or "indicator", yr, r[i])
        return out
    return out


def parse_file(path):
    """Return (source_tag, list_of_observations) or (source_tag, [])."""
    tag = os.path.relpath(path)
    obs = []
    try:
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            text = fh.read()
    except Exception as exc:
        print(f"[skip] {tag}: unreadable ({exc})")
        return tag, []
    stem = os.path.splitext(os.path.basename(path))[0]
    fwords = words_of(stem)
    fgeos, fmetric = roles_from_words(fwords)
    ext = os.path.splitext(path)[1].lower()

    try:
        if ext == ".json":
            obj = parse_json_text(text)
            if obj is None:
                print(f"[skip] {tag}: not parseable JSON")
                return tag, []
            if isinstance(obj, tuple):  # grid
                headers, rows = obj
                obs = grid_obs([str(h) for h in headers], rows, fgeos, fmetric)
            else:
                for pt, val in flatten_json(obj):
                    o = leaf_to_obs(pt, val, fgeos, fmetric)
                    if o:
                        obs.append(o)
        else:
            grid = parse_text_grid(text, fwords)
            if grid is None:
                # maybe JSON-ish anyway, or a simple two-column time series
                obj = parse_json_text(text)
                if obj is not None and isinstance(obj, dict):
                    for pt, val in flatten_json(obj):
                        o = leaf_to_obs(pt, val, fgeos, fmetric)
                        if o:
                            obs.append(o)
                else:
                    print(f"[skip] {tag}: no tabular structure detected")
                    return tag, []
            else:
                headers, rows = grid
                obs = grid_obs([str(h) for h in headers], rows, fgeos, fmetric)
    except Exception as exc:
        print(f"[warn] {tag}: parsing failed ({exc})")
        return tag, []
    return tag, obs

# ---------------------------------------------------------------------------
# Story analysis
# ---------------------------------------------------------------------------

def build_series(observations):
    """metric -> {geo: {year: value}}"""
    by_metric = {}
    for geo, metric, year, value in observations:
        m = by_metric.setdefault(metric, {})
        g = m.setdefault(geo, {})
        if year is not None:
            g[year] = value
        else:
            g.setdefault("_snapshot", value)
    return by_metric


def metric_coverage(series):
    out = []
    for metric, geos in series.items():
        yrs = set()
        total = 0
        for g, yd in geos.items():
            real = {y for y in yd if isinstance(y, int)}
            yrs |= real
            total += len(real) + (1 if "_snapshot" in yd else 0)
        out.append((metric, len(geos), len(yrs), total, min(yrs) if yrs else None,
                    max(yrs) if yrs else None))
    return out


def aggregate_series(geos_by_year_map, label="European aggregate"):
    """Return (dict year->value, kind, source_label)."""
    pref = ["European Union", "Euro area", "Europe"]
    cands = [g for g in pref if g in geos_by_year_map]
    if cands:
        best = max(cands, key=lambda g: sum(1 for y in geos_by_year_map[g]
                                            if isinstance(y, int)))
        data = {y: v for y, v in geos_by_year_map[best].items() if isinstance(y, int)}
        return data, "reported", best
    years = sorted({y for g in geos_by_year_map for y in geos_by_year_map[g]
                    if isinstance(y, int)})
    data = {}
    for y in years:
        vals = [geos_by_year_map[g][y] for g in geos_by_year_map if y in geos_by_year_map[g]]
        m = mean(vals)
        if m is not None:
            data[y] = m
    return data, "average", "mean of reported economies"


def trend_facts(data):
    years = sorted(data.keys())
    if not years:
        return None
    vals = [data[y] for y in years]
    first, last = vals[0], vals[-1]
    fy, ly = years[0], years[-1]
    yoy = (last - vals[-2]) if len(vals) >= 2 else None
    mn = min(range(len(vals)), key=lambda i: vals[i])
    mx = max(range(len(vals)), key=lambda i: vals[i])
    span = ly - fy
    cagr = None
    if span > 0 and first and last > 0:
        cagr = (last / first) ** (1 / span) - 1
    return {"years": years, "first": first, "last": last, "fy": fy, "ly": ly,
            "yoy": yoy, "min_year": years[mn], "min_val": vals[mn],
            "max_year": years[mx], "max_val": vals[mx],
            "span": span, "total": last - first, "cagr": cagr}


def direction_good(metric, change):
    if METRIC_DIR.get(metric) == "lower":
        return change < 0
    return change > 0


def latest_values(geo_year_map, metric):
    out = []
    for g, yd in geo_year_map.items():
        real = {y: v for y, v in yd.items() if isinstance(y, int)}
        if real:
            y = max(real)
            out.append((g, y, real[y], min(real), real[min(real)]))
        elif "_snapshot" in yd:
            out.append((g, None, yd["_snapshot"], None, None))
    return out

# ---------------------------------------------------------------------------
# Report assembly
# ---------------------------------------------------------------------------

def main():
    root = os.getcwd()
    print("=" * 72)
    print("EUROPEAN ECONOMIC PERFORMANCE - STORY REPORT BUILDER")
    print(f"workspace: {root}")
    files = discover_files(root)
    print(f"[1] candidate data files found: {len(files)}")
    observations = []
    sources = []
    for path in files:
        tag, obs = parse_file(path)
        sources.append((tag, len(obs)))
        observations.extend(obs)
        print(f"    {tag}: {len(obs)} observations")
    if observations:
        dedup = {}
        for o in observations:
            key = (o[0], o[1], o[2], round(o[3], 6))
            dedup.setdefault(key, o)
        observations = sorted(dedup.values(), key=lambda o: (o[1], o[0], o[2] or -1))
        print(f"[2] unique observations after dedup: {len(observations)}")

    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines = []
    lines.append("# The State of Europe's Economy: A Data Story")
    lines.append("")
    lines.append(f"> *Generated from workspace data on {now}*")

    if not observations:
        print("[!] no numeric observations were extracted - writing fallback report")
        lines.append("")
        lines.append("## What the data shows")
        lines.append("")
        lines.append("No structured numeric time series about European economic "
                     "performance could be located in this directory by the "
                     "discovery script. Candidate files inspected:")
        if sources:
            for tag, _n in sources:
                lines.append(f"- `{tag}`")
        else:
            lines.append("- (no candidate data files found)")
        lines.append("")
        lines.append("## Next step")
        lines.append("Add a CSV/JSON dataset (countries x years or tidy records) and "
                     "re-run the report builder.")
        with open(OUT_NAME, "w", encoding="utf-8") as fh:
            fh.write("\n".join(lines) + "\n")
        print(f"[done] report written: {OUT_NAME}")
        return

    series = build_series(observations)
    coverage = metric_coverage(series)
    print("[3] per-metric coverage (metric | geos | years | obs):")
    for c in sorted(coverage, key=lambda c: -c[3]):
        print(f"    {c[0]:<16} geos={c[1]:>3} years={c[2]:>3} obs={c[3]:>4} "
              f"({c[4]}..{c[5]})")

    hero = None
    for pref in HERO_PREFERENCE:
        for metric, ngeo, nyrs, total, y0, y1 in coverage:
            if metric == pref and ngeo >= 2 and (nyrs >= 2 or total >= 4):
                hero = metric
                break
        if hero:
            break
    if hero is None and coverage:
        hero = max(coverage, key=lambda c: (c[3]))
    if hero is None:
        hero = "indicator"

    label = METRIC_LABEL.get(hero, hero.replace("_", " ").title())
    geos_map = series[hero]
    agg_data, agg_kind, agg_src = aggregate_series(geos_map)
    facts = trend_facts(agg_data)
    print(f"[4] hero metric: {hero} ({label}); aggregate source: {agg_src} ({agg_kind})")

    # ----- context coverage -----
    real_obs = [o for o in observations if o[2] is not None]
    years_all = sorted({o[2] for o in real_obs})
    geos_all = sorted({o[0] for o in observations})
    econ_geos = sorted(g for g in geos_all if g not in AGGREGATE_GEOS)
    cover_years = f"{years_all[0]}–{years_all[-1]}" if years_all else "n/a"

    lines.append("")
    lines.append("## 1. The hook — one headline")
    lines.append("")

    if facts:
        delta = facts["total"]
        direction_word = ("up" if delta > 0 else "down")
        if hero == "unemployment":
            tone = ("falling unemployment is a sign of healing labour markets"
                    if delta < 0 else "rising unemployment is the central strain")
        elif hero == "inflation":
            tone = ("price pressure is easing" if delta < 0
                    else "price pressure is building")
        elif hero == "gdp_growth":
            tone = ("the economy is expanding faster than at the start of the period"
                    if delta > 0 else "growth momentum has cooled since the start of the period")
        elif hero == "debt":
            tone = ("public balance sheets are being repaired"
                    if delta < 0 else "public debt burdens are climbing")
        elif hero == "deficit":
            tone = ("fiscal balances are improving"
                    if delta > 0 else "fiscal positions are deteriorating")
        else:
            tone = f"the indicator moved {direction_word} over the period"
        lines.append(f"Across the economies in this dataset, **{label} went "
                     f"from {fmt_val(facts['first'], hero)} in {facts['fy']} to "
                     f"{fmt_val(facts['last'], hero)} in {facts['ly']}** "
                     f"({'+' if delta >= 0 else ''}{delta:+.2f} "
                     f"{'pp' if hero in PCT_METRICS else 'units'}) — {tone}.")
    else:
        lines.append(f"The headline indicator for this dataset is **{label}**.")

    lines.append("")
    lines.append("## 2. The context — where the numbers come from")
    lines.append("")
    lines.append(f"- **Indicator focus:** {label} (plus related metrics where available).")
    lines.append(f"- **Coverage:** {len(real_obs)} observations across "
                 f"{len(econ_geos)} European economies"
                 + (f" and {len(geos_all) - len(econ_geos)} aggregate blocks"
                    if len(geos_all) > len(econ_geos) else "")
                 + f", spanning {cover_years}.")
    lines.append(f"- **Aggregate used for trend reading:** {agg_src} "
                 f"({agg_kind}).")
    lines.append(f"- **Source files parsed:** "
                 + ", ".join(f"`{t}`" for t, _n in sources if _n)
                 + ("." if sources else "none."))

    # ----- trend -----
    lines.append("")
    lines.append("## 3. The arc — trend of the headline indicator")
    lines.append("")
    if facts and len(facts["years"]) >= 2:
        worst, best = (facts["min_year"], facts["min_val"]), (facts["max_year"], facts["max_val"])
        lines.append(f"The {agg_kind} series of **{label}** moved from "
                     f"{fmt_val(facts['first'], hero)} ({facts['fy']}) to "
                     f"{fmt_val(facts['last'], hero)} ({facts['ly']}). "
                     f"The lowest point was {fmt_val(worst[1], hero)} in {worst[0]} and "
                     f"the highest was {fmt_val(best[1], hero)} in {best[0]}.")
        if facts["yoy"] is not None:
            lines.append(f"In the final year of the sample, the indicator moved "
                         f"{'+' if facts['yoy'] >= 0 else ''}{facts['yoy']:+.2f} "
                         f"year-on-year — "
                         + ("continuing the recent direction."
                            if (facts["yoy"] >= 0) == (delta >= 0)
                            else "reversing the longer-run direction, a signal worth watching."))
        # build a compact year table
        trows = []
        for y in facts["years"]:
            trows.append([y, fmt_val(facts["y"], hero)])
        lines.append("")
        lines.append(md_table(["Year", f"{label} ({agg_src})"], trows))
        # momentum across economies
        real_lv = latest_values(geos_map, hero)
        movers = [(g, y, v) for g, y, v, _a, _b in real_lv if y is not None]
        imp = 0
        for g, y, v in movers:
            if y - 1 in geos_map[g] and geos_map[g][y - 1] is not None:
                if direction_good(hero, v - geos_map[g][y - 1]):
                    imp += 1
        if imp:
            lines.append("")
            lines.append(f"In the latest year with comparable data, "
                         f"**{imp} of {len(movers)}** economies moved in the "
                         "favourable direction for this indicator.")
    else:
        lines.append("The dataset contains mostly a single-period snapshot, so the "
                     "story is comparative rather than a time arc.")

    # ----- dispersion / leaders-laggards -----
    lines.append("")
    lines.append("## 4. The divide — leaders and laggards")
    lines.append("")
    real_lv = latest_values(geos_map, hero)
    comp = [(g, y, v) for g, y, v, _a, _b in real_lv if g not in AGGREGATE_GEOS]
    comp.sort(key=lambda t: t[2], reverse=(METRIC_DIR.get(hero, "higher") == "higher"))
    if len(comp) >= 2:
        vals = [v for _, _, v in comp]
        sd = stdev(vals)
        lines.append(f"Ranking economies by their most recent {label}, the spread is "
                     f"**{fmt_val(max(vals), hero)} vs {fmt_val(min(vals), hero)}** "
                     f"(standard deviation {sd:,.2f} if sd is not None else 'n/a'). "
                     "This gap is the story underneath the aggregate: averages hide "
                     "divergence.")
        rows = []
        for g, y, v in comp:
            rows.append([g, y if y is not None else "latest",
                         fmt_val(v, hero)])
        lines.append("")
        lines.append(md_table(["Economy", "Year", f"{label} (latest)"], rows))
        if len(comp) >= 3:
            top = comp[:3]
            bot = comp[-3:]
            lines.append("")
            lines.append(f"The strongest recent readings come from "
                         + ", ".join(f"{g} ({fmt_val(v, hero)})" for g, _y, v in top)
                         + f"; the weakest from "
                         + ", ".join(f"{g} ({fmt_val(v, hero)})" for g, _y, v in bot)
                         + ".")
    else:
        lines.append("Not enough economies with recent values for a meaningful ranking.")

    # ----- related metrics table -----
    sec = []
    for metric, ngeo, nyrs, total, _y0, _y1 in coverage:
        if metric == hero:
            continue
        if ngeo >= 3:
            sec.append(metric)
    if sec:
        lines.append("")
        lines.append("## 5. The wider dashboard — related indicators")
        lines.append("")
        lines.append("The same dataset also allows a multi-indicator view. Latest "
                     "available readings per economy:")
        lines.append("")
        headers = ["Economy"] + [METRIC_LABEL.get(m, m) for m in sec]
        rows = []
        geo_choice = sorted({g for g in geos_all if g not in AGGREGATE_GEOS})
        for g in geo_choice:
            row = [g]
            for m in sec:
                lv = latest_values(series[m], m)
                hit = [v for gg, _y, v, _a, _b in lv if gg == g]
                row.append(fmt_val(hit[0], m) if hit else "n/a")
            rows.append(row)
        lines.append(md_table(headers, rows))

    # ----- cross-metric insights -----
    lines.append("")
    lines.append("## 6. What the crossovers say — correlations in the data")
    lines.append("")
    present = [c[0] for c in coverage]
    pairs = []
    for i, a in enumerate(present):
        for b in present[i + 1:]:
            if a == b:
                continue
            pa = []
            pb = []
            for g in series[a]:
                if g in series[b]:
                    va = latest_values(series[a], a)
                    vb = latest_values(series[b], b)
                    da = {gg: v for gg, _y, v, _a2, _b2 in va}
                    db = {gg: v for gg, _y, v, _a2, _b2 in vb}
                    if g in da and g in db:
                        pa.append(da[g])
                        pb.append(db[g])
            r, n = pearson(pa, pb)
            if r is not None and n >= 5:
                pairs.append((abs(r), r, n, a, b))
    pairs.sort(reverse=True)
    if pairs:
        used = set()
        shown = 0
        for _absr, r, n, a, b in pairs:
            key = frozenset((a, b))
            if key in used:
                continue
            used.add(key)
            la = METRIC_LABEL.get(a, a)
            lb = METRIC_LABEL.get(b, b)
            sense = "tend to move together" if r >= 0 else "tend to move in opposite directions"
            lines.append(f"- Across {n} economies, **{la}** and **{lb}** {sense} "
                         f"(correlation ≈ {r:+.2f}). This is an association, not proof "
                         "of causation — treat it as a pattern worth explaining.")
            shown += 1
            if shown >= 3:
                break
        if not shown:
            lines.append("No robust pairwise patterns with five or more overlapping "
                         "economies were found.")
    else:
        lines.append("No robust pairwise patterns with five or more overlapping "
                     "economies were found in this dataset.")

    # ----- key insights & implication -----
    lines.append("")
    lines.append("## 7. The insight — three things the data says")
    lines.append("")
    insights = []
    if facts and len(comp) >= 2:
        span_hi = None
        best_run = None
        for g, y, v, y0, v0 in [(g, y, v, a, b) for g, y, v, a, b in real_lv
                                if g not in AGGREGATE_GEOS and y is not None and y0 is not None]:
            if y0 != y:
                chg = v - v0
                if best_run is None or abs(chg) > abs(best_run[1]):
                    best_run = (g, chg, y0, y, v0, v)
        if best_run:
            chg = best_run[1]
            good = direction_good(hero, chg)
            insights.append(f"**The biggest single-economy move:** "
                            f"{best_run[0]} moved from {fmt_val(best_run[4], hero)} "
                            f"({best_run[2]}) to {fmt_val(best_run[5], hero)} "
                            f"({best_run[3]}), a {'+' if chg >= 0 else ''}{chg:+.2f}-point "
                            f"shift {'in the favourable direction' if good else 'to watch'}.")
    if facts and len(comp) >= 2:
        vals = [v for _, _, v in comp]
        insights.append(f"**Divergence is real:** the most recent readings for {label} "
                        f"range from {fmt_val(min(vals), hero)} to "
                        f"{fmt_val(max(vals), hero)} across {len(comp)} economies — "
                        "European performance is not a single number but a band.")
    if facts:
        insights.append(f"**Timing matters:** the {agg_kind} series bottomed at "
                        f"{fmt_val(facts['min_val'], hero)} in {facts['min_year']} and "
                        f"closed the sample at {fmt_val(facts['last'], hero)} in "
                        f"{facts['ly']} — what happened between those dates, and which "
                        "policies accompanied it, is the question for the next analysis.")
    if pairs:
        _absr, r, n, a, b = pairs[0]
        insights.append(f"**The strongest cross-link** in this dataset pairs "
                        f"**{METRIC_LABEL.get(a, a)}** with **{METRIC_LABEL.get(b, b)}** "
                        f"(r ≈ {r:+.2f}, n = {n}) — if one is part of the story, the "
                        "other is probably part of the explanation.")
    if not insights:
        insights.append("The dataset supports a snapshot comparison; a longer time "
                        "series would sharpen the causal story.")
    for ins in insights[:3]:
        lines.append(f"- {ins}")

    lines.append("")
    lines.append("## 8. The implication and next question")
    lines.append("")
    lines.append(f"European performance is **improving on balance but unevenly**: the "
                 f"aggregate {label} trend tells one story, while the country-level "
                 f"band tells another. The actionable next step for any stakeholder is "
                 f"to ask **why the leaders lead and the laggards lag** — decomposing "
                 "the gap by structure (exports, fiscal space, labour markets) before "
                 "setting targets. The numbers in this report are the evidence base "
                 "for that discussion.")
    lines.append("")
    lines.append("## 9. Call to action")
    lines.append("")
    lines.append("- **Decide** which economies define 'success' for this metric and "
                 "benchmark against them explicitly.")
    lines.append("- **Investigate** the strongest correlation found above before "
                 "assuming causation.")
    lines.append("- **Update** this report when the next year of data lands — trend "
                 "stories get stronger with each new observation.")
    lines.append("")

    lines.append("---")
    lines.append("")
    lines.append("### Method note (honesty box)")
    lines.append("")
    lines.append(f"- Values are used **as reported** in the source files; units "
                 f"(% vs levels) follow each source's own convention.")
    lines.append(f"- Series were normalised with heuristics: "
                 f"{len(observations)} observations after de-duplication; aggregate "
                 f"series are {'reported aggregates' if agg_kind == 'reported' else 'simple cross-country means'}.")
    lines.append("- Correlations are computed on latest available overlapping values "
                 "and describe association only.")
    lines.append("- Source files parsed: "
                 + "; ".join(f"`{t}` ({n} obs)" for t, n in sources if n)
                 + ".")

    report = "\n".join(lines) + "\n"
    with open(OUT_NAME, "w", encoding="utf-8") as fh:
        fh.write(report)
    print(f"[5] report written: {OUT_NAME} ({len(report)} bytes)")
    print("[6] first lines of the report:")
    for ln in report.splitlines()[:8]:
        print("   " + ln)


if __name__ == "__main__":
    main()

