#!/usr/bin/env python3
"""Task-local discovery helper: inventory European economic data files in the workspace."""
import os

ROOT = os.getcwd()
print("WORKSPACE ROOT:", ROOT)
print("=" * 72)

skip_dirs = {".git", "__pycache__"}

def walk(path, depth=0):
    if depth > 4:
        return
    try:
        entries = sorted(os.listdir(path))
    except OSError as exc:
        print(f"[unreadable] {path}: {exc}")
        return
    for name in entries:
        full = os.path.join(path, name)
        if os.path.isdir(full):
            if name in skip_dirs:
                continue
            print(f"\n[DIR] {full}/")
            walk(full, depth + 1)
        else:
            try:
                size = os.path.getsize(full)
            except OSError:
                size = -1
            print(f"[FILE] {full}  ({size} bytes)")
            if size >= 0 and size <= 1_500_000:
                try:
                    with open(full, "r", encoding="utf-8", errors="replace") as fh:
                        head = fh.read(4000)
                    print("--- preview (first 4000 chars) ---")
                    print(head)
                    print("--- end preview ---")
                except Exception as exc:  # pragma: no cover - defensive
                    print(f"[preview failed] {exc}")

walk(ROOT)
print("\nDISCOVERY COMPLETE")

#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
European economic performance -> data storytelling report builder.

Discovers candidate data files in the current workspace, normalizes numeric
records into (geo, metric, year, value) observations using light heuristics,
derives story facts (trends, rankings, dispersion, cross-metric relations),
and writes a Markdown data-storytelling report artifact.
"""
import csv
import json
import math
import os
import re
from datetime import datetime, timezone

OUT_NAME = "european_economic_performance_story.md"

# ---------------------------------------------------------------------------
# Dictionaries used by the heuristic normalizer
# ---------------------------------------------------------------------------

COUNTRY_ALIASES = {
    "Germany": ["germany", "german", "deu"],
    "France": ["france", "fra"],
    "Italy": ["italy", "ita"],
    "Spain": ["spain", "esp"],
    "Netherlands": ["netherlands", "holland", "nld"],
    "Belgium": ["belgium", "bel"],
    "Austria": ["austria", "aut"],
    "Portugal": ["portugal", "prt"],
    "Greece": ["greece", "grc"],
    "Ireland": ["ireland", "irl"],
    "Finland": ["finland", "fin"],
    "Sweden": ["sweden", "swe"],
    "Denmark": ["denmark", "dnk"],
    "Poland": ["poland", "pol"],
    "Czechia": ["czech republic", "czechia", "czech", "cze"],
    "Slovakia": ["slovakia", "slovak republic", "svk"],
    "Slovenia": ["slovenia", "svn"],
    "Hungary": ["hungary", "hun"],
    "Romania": ["romania", "rou"],
    "Bulgaria": ["bulgaria", "bgr"],
    "Croatia": ["croatia", "hrv"],
    "Estonia": ["estonia", "est"],
    "Latvia": ["latvia", "lva"],
    "Lithuania": ["lithuania", "ltu"],
    "Luxembourg": ["luxembourg", "lux"],
    "Cyprus": ["cyprus", "cyp"],
    "Malta": ["malta", "mlt"],
    "United Kingdom": ["united kingdom", "britain", "uk", "gbr"],
    "United States": ["united states", "usa", "us"],
    "Euro area": ["euro area", "eurozone", "euro area countries", "ea20", "ea19", "ea"],
    "European Union": ["european union", "eu27", "eu 27", "eu"],
    "Europe": ["europe"],
    "Norway": ["norway", "nor"],
    "Switzerland": ["switzerland", "swiss", "che"],
    "Iceland": ["iceland", "isl"],
    "Turkey": ["turkey", "tur"],
}

AGGREGATE_GEOS = {"European Union", "Euro area", "Europe"}

# ordered metric specs: (key, display label, synonym fragments, direction)
METRIC_SPECS = [
    ("gdp_per_capita", "GDP per capita", ["gdppercapita", "percapitagdp", "gdppc"], "higher"),
    ("gdp_growth", "GDP growth", ["gdpgrowth", "gdp growth", "realgdpgrowth",
                                  "economicgrowth", "economygrowth", "real gdp"], "higher"),
    ("inflation", "Inflation (HICP/CPI)", ["inflation", "hicp", "consumerpriceindex",
                                           "cpi"], "lower"),
    ("unemployment", "Unemployment", ["unemployment", "jobless"], "lower"),
    ("deficit", "Government balance / deficit", ["deficit", "budgetbalance",
                                                 "governmentbalance", "fiscalbalance",
                                                 "netlending"], "higher"),
    ("debt", "Government debt", ["governmentdebt", "publicdebt", "debttogdp", "debt"], "lower"),
    ("gdp", "GDP (level)", ["gdp", "grossdomesticproduct"], "higher"),
    ("productivity", "Productivity", ["productivity", "labourproductivity",
                                      "laborproductivity"], "higher"),
    ("exports", "Exports", ["exports", "export"], "higher"),
    ("imports", "Imports", ["imports", "import"], "higher"),
    ("current_account", "Current account", ["currentaccount", "current account"], "higher"),
    ("employment", "Employment", ["employment"], "higher"),
    ("investment", "Investment", ["investment", "grossfixedcapital"], "higher"),
    ("interest_rate", "Interest rate", ["interestrate", "interest rate",
                                        "longterminterest"], "lower"),
    ("consumption", "Consumption", ["consumption"], "higher"),
    ("population", "Population", ["population"], "higher"),
]

METRIC_LABEL = {k: lab for k, lab, _syn, _d in METRIC_SPECS}
METRIC_DIR = {k: d for k, _lab, _syn, d in METRIC_SPECS}
PCT_METRICS = {"gdp_growth", "unemployment", "inflation", "deficit", "interest_rate",
               "employment"}

HERO_PREFERENCE = ["gdp_growth", "unemployment", "inflation", "deficit", "debt",
                   "gdp_per_capita", "gdp", "exports", "imports", "employment",
                   "productivity", "investment", "current_account", "interest_rate",
                   "consumption", "population"]

ALIAS_CANDIDATES = []
for _canon, _aliases in COUNTRY_ALIASES.items():
    for _a in _aliases:
        ALIAS_CANDIDATES.append((_a, _canon))
ALIAS_CANDIDATES.sort(key=lambda t: (len(t[0].split()), len(t[0])), reverse=True)

GEO_WORDS = {"country", "geo", "geography", "area", "region", "member state",
             "economy", "jurisdiction", "nation", "territory", "country/area",
             "country area"}
YEAR_WORDS = {"year", "date", "period", "time", "observation date"}

# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def safe_float(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if math.isnan(f) or math.isinf(f):
        return None
    return f


def words_of(text):
    return re.findall(r"[a-z]+", text.lower())


def nospace_of(words):
    return "".join(words)


def years_of(text):
    return sorted({int(y) for y in re.findall(r"(?<!\d)(?:19|20)\d\d(?!\d)", text)
                   if 1950 <= int(y) <= 2035})


def alias_in_words(words, alias):
    parts = alias.split()
    if not parts:
        return False
    if len(parts) == 1:
        p = parts[0]
        if len(p) <= 3:
            return p in words
        return any((p in w) or (w in p) for w in words)
    for i in range(len(words) - len(parts) + 1):
        if words[i:i + len(parts)] == parts:
            return True
    return False


def metric_from_words(words, weak=False):
    txt = nospace_of(words)
    for key, _lab, syns, _d in METRIC_SPECS:
        for s in syns:
            sn = re.sub(r"[^a-z0-9]", "", s.lower())
            if sn and sn in txt:
                return key
    if weak:
        if "growth" in words:
            return "gdp_growth"
        if "rate" in words and "unemployment" in txt:
            return "unemployment"
    return None


def roles_from_words(words):
    geos = set()
    for alias, canon in ALIAS_CANDIDATES:
        if alias_in_words(words, alias):
            geos.add(canon)
    metric = metric_from_words(words)
    return geos, metric


def slugify(text):
    return re.sub(r"[^a-z0-9]+", "_", str(text).lower()).strip("_") or "value"


def mean(xs):
    xs = [x for x in xs if x is not None]
    return sum(xs) / len(xs) if xs else None


def stdev(xs):
    xs = [x for x in xs if x is not None]
    if len(xs) < 2:
        return None
    m = sum(xs) / len(xs)
    return math.sqrt(sum((x - m) ** 2 for x in xs) / (len(xs) - 1))


def pearson(xs, ys):
    pairs = [(x, y) for x, y in zip(xs, ys) if x is not None and y is not None]
    if len(pairs) < 3:
        return None, 0
    xs = [p[0] for p in pairs]
    ys = [p[1] for p in pairs]
    mx, my = mean(xs), mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return None, len(pairs)
    return num / (dx * dy), len(pairs)


def fmt_val(v, metric):
    if v is None:
        return "n/a"
    if metric in PCT_METRICS:
        return f"{v:,.2f}%"
    if abs(v) >= 1000:
        return f"{v:,.1f}"
    return f"{v:,.2f}"


def md_table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "| " + " | ".join(["---"] * len(headers)) + " |"]
    for r in rows:
        out.append("| " + " | ".join(str(c) for c in r) + " |")
    return "\n".join(out)

