def build_series(observations):
    """metric -> {geo: {year: value}}"""
    by_metric = {}
    for geo, metric, year, value in observations:
        m = by_metric.setdefault(metric, {})
        g = m.setdefault(geo, {})
        if year is not None:
            g[year] = value
        else:
            g.setdefault("_snapshot", value)
    return by_metric


def metric_coverage(series):
    out = []
    for metric, geos in series.items():
        yrs = set()
        total = 0
        for g, yd in geos.items():
            real = {y for y in yd if isinstance(y, int)}
            yrs |= real
            total += len(real) + (1 if "_snapshot" in yd else 0)
        out.append((metric, len(geos), len(yrs), total, min(yrs) if yrs else None,
                    max(yrs) if yrs else None))
    return out


def aggregate_series(geos_by_year_map, label="European aggregate"):
    """Return (dict year->value, kind, source_label)."""
    pref = ["European Union", "Euro area", "Europe"]
    cands = [g for g in pref if g in geos_by_year_map]
    if cands:
        best = max(cands, key=lambda g: sum(1 for y in geos_by_year_map[g]
                                            if isinstance(y, int)))
        data = {y: v for y, v in geos_by_year_map[best].items() if isinstance(y, int)}
        return data, "reported", best
    years = sorted({y for g in geos_by_year_map for y in geos_by_year_map[g]
                    if isinstance(y, int)})
    data = {}
    for y in years:
        vals = [geos_by_year_map[g][y] for g in geos_by_year_map if y in geos_by_year_map[g]]
        m = mean(vals)
        if m is not None:
            data[y] = m
    return data, "average", "mean of reported economies"


def trend_facts(data):
    years = sorted(data.keys())
    if not years:
        return None
    vals = [data[y] for y in years]
    first, last = vals[0], vals[-1]
    fy, ly = years[0], years[-1]
    yoy = (last - vals[-2]) if len(vals) >= 2 else None
    mn = min(range(len(vals)), key=lambda i: vals[i])
    mx = max(range(len(vals)), key=lambda i: vals[i])
    span = ly - fy
    cagr = None
    if span > 0 and first and last > 0:
        cagr = (last / first) ** (1 / span) - 1
    return {"years": years, "first": first, "last": last, "fy": fy, "ly": ly,
            "yoy": yoy, "min_year": years[mn], "min_val": vals[mn],
            "max_year": years[mx], "max_val": vals[mx],
            "span": span, "total": last - first, "cagr": cagr}


def direction_good(metric, change):
    if METRIC_DIR.get(metric) == "lower":
        return change < 0
    return change > 0


def latest_values(geo_year_map, metric):
    out = []
    for g, yd in geo_year_map.items():
        real = {y: v for y, v in yd.items() if isinstance(y, int)}
        if real:
            y = max(real)
            out.append((g, y, real[y], min(real), real[min(real)]))
        elif "_snapshot" in yd:
            out.append((g, None, yd["_snapshot"], None, None))
    return out

