"""Task-scoped helper: locate and digest European economic performance data
present in the workspace, to support the requested data storytelling report."""
import csv
import json
import os
from pathlib import Path

BASE = Path(__file__).resolve().parent
SKIP_DIRS = {'.codex', '__pycache__', '.git', 'node_modules', '.venv'}
EXTENSIONS = {'.csv', '.tsv', '.txt', '.json'}


def main():
    print('WORKSPACE_BASE:', BASE)
    print('CWD:', Path.cwd())
    candidates = []
    for root, dirs, files in os.walk(BASE):
        dirs[:] = [d for d in dirs if d not in SKIP_DIRS]
        for fn in sorted(files):
            p = Path(root) / fn
            if p.suffix.lower() in EXTENSIONS:
                candidates.append(p)
    print('CANDIDATE_FILES:', [str(p.relative_to(BASE)) for p in candidates])

    for p in candidates:
        print('\n==== FILE:', p.relative_to(BASE), '====')
        try:
            if p.suffix.lower() == '.json':
                with p.open(encoding='utf-8') as fh:
                    data = json.load(fh)
                print(json.dumps(data, indent=2, default=str)[:8000])
            else:
                with p.open(encoding='utf-8', errors='replace') as fh:
                    print(fh.read(8000))
        except Exception as exc:  # noqa: BLE001 - digest must not abort
            print('ERROR reading file:', exc)


if __name__ == '__main__':
    main()

