]

METRIC_LABEL = {k: lab for k, lab, _syn, _d in METRIC_SPECS}
METRIC_DIR = {k: d for k, _lab, _syn, d in METRIC_SPECS}
PCT_METRICS = {"gdp_growth", "unemployment", "inflation", "deficit", "interest_rate",
               "employment"}

HERO_PREFERENCE = ["gdp_growth", "unemployment", "inflation", "deficit", "debt",
                   "gdp_per_capita", "gdp", "exports", "imports", "employment",
                   "productivity", "investment", "current_account", "interest_rate",
                   "consumption", "population"]

ALIAS_CANDIDATES = []
for _canon, _aliases in COUNTRY_ALIASES.items():
    for _a in _aliases:
        ALIAS_CANDIDATES.append((_a, _canon))
ALIAS_CANDIDATES.sort(key=lambda t: (len(t[0].split()), len(t[0])), reverse=True)

GEO_WORDS = {"country", "geo", "geography", "area", "region", "member state",
             "economy", "jurisdiction", "nation", "territory", "country/area",
             "country area"}
YEAR_WORDS = {"year", "date", "period", "time", "observation date"}

# ---------------------------------------------------------------------------
# Small helpers
# ---------------------------------------------------------------------------

def safe_float(v):
    if v is None:
        return None
    if isinstance(v, bool):
        return None
    try:
        f = float(v)
    except (TypeError, ValueError):
        return None
    if math.isnan(f) or math.isinf(f):
        return None
    return f


def words_of(text):
    return re.findall(r"[a-z]+", text.lower())


def nospace_of(words):
    return "".join(words)


def years_of(text):
    return sorted({int(y) for y in re.findall(r"(?<!\d)(?:19|20)\d\d(?!\d)", text)
                   if 1950 <= int(y) <= 2035})


def alias_in_words(words, alias):
    parts = alias.split()
    if not parts:
        return False
    if len(parts) == 1:
        p = parts[0]
        if len(p) <= 3:
            return p in words
        return any((p in w) or (w in p) for w in words)
    for i in range(len(words) - len(parts) + 1):
        if words[i:i + len(parts)] == parts:
            return True
    return False


def metric_from_words(words, weak=False):
    txt = nospace_of(words)
    for key, _lab, syns, _d in METRIC_SPECS:
        for s in syns:
            sn = re.sub(r"[^a-z0-9]", "", s.lower())
            if sn and sn in txt:
                return key
    if weak:
        if "growth" in words:
            return "gdp_growth"
        if "rate" in words and "unemployment" in txt:
            return "unemployment"
    return None


def roles_from_words(words):
    geos = set()
    for alias, canon in ALIAS_CANDIDATES:
        if alias_in_words(words, alias):
            geos.add(canon)
    metric = metric_from_words(words)
    return geos, metric


def slugify(text):
    return re.sub(r"[^a-z0-9]+", "_", str(text).lower()).strip("_") or "value"


def mean(xs):
    xs = [x for x in xs if x is not None]
    return sum(xs) / len(xs) if xs else None


def stdev(xs):
    xs = [x for x in xs if x is not None]
    if len(xs) < 2:
        return None
    m = sum(xs) / len(xs)
    return math.sqrt(sum((x - m) ** 2 for x in xs) / (len(xs) - 1))


def pearson(xs, ys):
    pairs = [(x, y) for x, y in zip(xs, ys) if x is not None and y is not None]
    if len(pairs) < 3:
        return None, 0
    xs = [p[0] for p in pairs]
    ys = [p[1] for p in pairs]
    mx, my = mean(xs), mean(ys)
    num = sum((x - mx) * (y - my) for x, y in zip(xs, ys))
    dx = math.sqrt(sum((x - mx) ** 2 for x in xs))
    dy = math.sqrt(sum((y - my) ** 2 for y in ys))
    if dx == 0 or dy == 0:
        return None, len(pairs)
    return num / (dx * dy), len(pairs)


def fmt_val(v, metric):
    if v is None:
        return "n/a"
    if metric in PCT_METRICS:
        return f"{v:,.2f}%"
    if abs(v) >= 1000:
        return f"{v:,.1f}"
    return f"{v:,.2f}"


def md_table(headers, rows):
    out = ["| " + " | ".join(headers) + " |",
           "| " + " | ".join(["---"] * len(headers)) + " |"]
    for r in rows:
        out.append("| " + " | ".join(str(c) for c in r) + " |")
    return "\n".join(out)

# ---------------------------------------------------------------------------
# Discovery / parsing
# ---------------------------------------------------------------------------

def discover_files(root):
    found = []
    for dirpath, dirnames, filenames in os.walk(root):
        dirnames[:] = [d for d in dirnames if not d.startswith(".")
                       and d != "__pycache__"]
        for fn in sorted(filenames):
            ext = os.path.splitext(fn)[1].lower()
            if ext in (".json", ".csv", ".tsv", ".txt", ".md", ".dat", ".data"):
                if fn == OUT_NAME:
                    continue
                found.append(os.path.join(dirpath, fn))
    return sorted(found)


def parse_json_text(text):
    """Return a grid (headers, rows-of-lists) or a nested dict or None."""
    try:
        obj = json.loads(text)
    except Exception:
        return None
    if isinstance(obj, dict):
        return obj
    if isinstance(obj, list):
        if not obj:
            return None
        if all(isinstance(r, dict) for r in obj):
            headers = []
            for r in obj:
                for k in r.keys():
                    if k not in headers:
                        headers.append(k)
            rows = [[r.get(h) for h in headers] for r in obj]
            return (headers, rows)
        if all(isinstance(r, list) for r in obj):
            widths = {len(r) for r in obj}
            if len(widths) == 1 and obj:
                return (list(range(len(obj[0]))), obj)
    return None


def flatten_json(obj, path=()):
    """Yield (path_tokens, scalar) leaves of a JSON dict structure."""
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from flatten_json(v, path + (str(k),))
    elif isinstance(obj, list):
        for i, v in enumerate(obj):
            yield from flatten_json(v, path + (str(i),))
    else:
        yield path, obj


def detect_delimiter(text):
    lines = text.splitlines()[:6]
    best, bestn = ",", 0
    for d in [";", "\t", "|", ","]:
        counts = []
        for line in lines:
            if d in line:
                counts.append(len(line.split(d)))
        if counts:
            n = max(counts) - min(counts)
            med = sorted(counts)[len(counts) // 2]
            score = med if n <= 1 else 0
            if score > bestn:
                bestn, best = score, d
    return best


def rows_from_csv_text(text):
    delim = detect_delimiter(text)
    reader = csv.reader(text.splitlines(), delimiter=delim)
    rows = [r for r in reader if r and any(c.strip() for c in r)]
    if not rows:
        return None
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    # skip separator rows like |---|---|
    rows = [r for r in rows if not all(re.fullmatch(r"[\s:\-]+", c) for c in r if c)]
    return rows


def rows_from_pipe_table(text):
    lines = [ln.strip() for ln in text.splitlines() if "|" in ln]
    rows = []
    for ln in lines:
        cells = [c.strip() for c in ln.strip("|").split("|")]
        if len(cells) >= 3:
            rows.append(cells)
    rows = [r for r in rows if not all(re.fullmatch(r"[\s:\-]+", c) for c in r)]
    if len(rows) < 2:
        return None
    width = max(len(r) for r in rows)
    rows = [r + [""] * (width - len(r)) for r in rows]
    return rows


def parse_text_grid(text, file_words):
    """Return a grid (headers, rows) if the text looks tabular."""
    rows = rows_from_pipe_table(text)
    if rows is None:
        try:
            rows = rows_from_csv_text(text)
        except Exception:
            rows = None
    if rows is None or len(rows) < 2:
        return None
    return (rows[0], rows[1:])


# ---------------------------------------------------------------------------
# Observation building
# ---------------------------------------------------------------------------

def leaf_to_obs(path_tokens, value, fgeos, fmetric):
    raw = " ".join(str(p) for p in path_tokens)
    years = years_of(raw)
    lgeos, lmetric = roles_from_words(words_of(raw))
    if len(lgeos) > 1:
        return None
    if not lgeos and len(fgeos) == 1:
        lgeos = set(fgeos)
    if not lgeos:
        return None
    geo = next(iter(lgeos))
    metric = lmetric or fmetric
    if not years:
        return None
    year = max(years)
    num = safe_float(value)
    if num is None:
        return None
    return (geo, metric or "indicator", year, num)


def grid_obs(headers, rows, fgeos, fmetric):
    """Heuristic conversion of a tabular grid into observations."""
    if not headers or not rows:
        return []
    out = []
    n = len(headers)
    infos = []
    for h in headers:
        hs = str(h).strip()
        low = hs.lower()
        words = words_of(hs)
        geos, metric = roles_from_words(words)
        infos.append({"geo": geos, "metric": metric, "text": hs,
                      "is_geo_word": low in GEO_WORDS,
                      "is_year_word": low in YEAR_WORDS,
                      "is_bare_year": bool(re.fullmatch(r"(?:19|20)\d\d", hs)),
                      "geo_only": len(geos) == 1 and not metric and not infos[-1]["text"].lower() in GEO_WORDS if infos else len(geos) == 1 and not metric})
    # fix geo_only awkwardness by recomputing
    infos = []
    for h in headers:
        hs = str(h).strip()
        low = hs.lower()
        words = words_of(hs)
        geos, metric = roles_from_words(words)
        infos.append({"geo": geos, "metric": metric, "text": hs,
                      "is_geo_word": low in GEO_WORDS,
                      "is_year_word": low in YEAR_WORDS,
                      "is_bare_year": bool(re.fullmatch(r"(?:19|20)\d\d", hs))})

    geo_idx = None
    year_idx = None
    for i, info in enumerate(infos):
        if info["is_geo_word"] and geo_idx is None:
            geo_idx = i
        if info["is_year_word"] and year_idx is None:
            year_idx = i

    # majority-country column fallback for geo
    if geo_idx is None and n:
        best, best_frac = None, 0.0
        for i in range(n):
            vals = [r[i] for r in rows if i < len(r)]
            if not vals:
                continue
            hits = 0
            for v in vals:
                gs, _m = roles_from_words(words_of(str(v)))
                if len(gs) == 1:
                    hits += 1
            frac = hits / len(vals)
            if frac >= 0.6 and frac > best_frac:
                best_frac, best = frac, i
        geo_idx = best

    def geo_from_cell(v):
        gs, _m = roles_from_words(words_of(str(v)))
        if len(gs) == 1:
            return next(iter(gs))
        return None

    def year_from_cell(v):
        ys = years_of(str(v))
        return ys[-1] if ys else None

    def add(geo, metric, year, value):
        num = safe_float(value)
        if geo and num is not None:
            out.append((geo, metric or "indicator", year, num))

    # Tidy long format: one geo column + one year column, others are metrics
    if geo_idx is not None and year_idx is not None:
        for r in rows:
            if year_idx >= len(r) or geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            yr = year_from_cell(r[year_idx])
            if not geo or yr is None:
                continue
            for i, h in enumerate(headers):
                if i in (geo_idx, year_idx) or i >= len(r):
                    continue
                metric = infos[i]["metric"] or slugify(infos[i]["text"])
                add(geo, metric, yr, r[i])
        return out

    # Wide format A: country rows, bare-year columns
    bare_year_cols = [i for i, info in enumerate(infos) if info["is_bare_year"]]
    if geo_idx is not None and bare_year_cols and year_idx is None:
        other_metric_cols = [i for i in range(n)
                             if i not in bare_year_cols and i != geo_idx
                             and infos[i]["metric"]]
        default_metric = fmetric or "indicator"
        for r in rows:
            if geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            if not geo:
                continue
            for ci in bare_year_cols:
                if ci >= len(r):
                    continue
                add(geo, default_metric, int(infos[ci]["text"]), r[ci])
            for ci in other_metric_cols:
                if ci >= len(r):
                    continue
                yr = year_from_cell(r[geo_idx]) if False else None
                add(geo, infos[ci]["metric"], yr, r[ci])
        return out

    # Wide format B: year rows, geo-name columns
    geo_cols = [i for i, info in enumerate(infos) if len(info["geo"]) == 1
                and not info["is_geo_word"] and not info["is_year_word"]
                and not info["is_bare_year"]]
    if year_idx is not None and geo_cols:
        metric = fmetric or "indicator"
        for r in rows:
            if year_idx >= len(r):
                continue
            yr = year_from_cell(r[year_idx])
            if yr is None:
                continue
            for ci in geo_cols:
                if ci >= len(r):
                    continue
                add(next(iter(infos[ci]["geo"])), metric, yr, r[ci])
        return out

    # Rows of countries with metric columns (no year info): snapshot obs
    if geo_idx is not None:
        for r in rows:
            if geo_idx >= len(r):
                continue
            geo = geo_from_cell(r[geo_idx])
            if not geo:
                continue
            for i, h in enumerate(headers):
                if i == geo_idx or i >= len(r):
                    continue
                metric = infos[i]["metric"] or slugify(infos[i]["text"])
                add(geo, metric, None, r[i])
        return out

    # Time series per metric column with a single geo from filename
    if year_idx is not None and len(fgeos) == 1:
        geo = next(iter(fgeos))
        metric = fmetric or "indicator"
        for r in rows:
            if year_idx >= len(r):
                continue
            yr = year_from_cell(r[year_idx])
            if yr is None:
                continue
            for i, h in enumerate(headers):
                if i == year_idx or i >= len(r):
                    continue
                add(geo, infos[i]["metric"] or metric, yr, r[i])
        return out

    # Last resort: first column numeric looks like years, first row headers metrics
    first_vals = [safe_float(r[0]) for r in rows]
    first_years = [year_from_cell(r[0]) for r in rows]
    if first_years and all(y is not None for y in first_years[:3]) and len(fgeos) == 1:
        geo = next(iter(fgeos))
        for r in rows:
            yr = year_from_cell(r[0])
            if yr is None:
                continue
            for i, h in enumerate(headers):
                if i == 0 or i >= len(r):
                    continue
                add(geo, infos[i]["metric"] or fmetric or "indicator", yr, r[i])
        return out
    return out


def parse_file(path):
    """Return (source_tag, list_of_observations) or (source_tag, [])."""
    tag = os.path.relpath(path)
    obs = []
    try:
        with open(path, "r", encoding="utf-8-sig", errors="replace") as fh:
            text = fh.read()
    except Exception as exc:
        print(f"[skip] {tag}: unreadable ({exc})")
        return tag, []
    stem = os.path.splitext(os.path.basename(path))[0]
    fwords = words_of(stem)
    fgeos, fmetric = roles_from_words(fwords)
    ext = os.path.splitext(path)[1].lower()

    try:
        if ext == ".json":
            obj = parse_json_text(text)
            if obj is None:
                print(f"[skip] {tag}: not parseable JSON")
                return tag, []
            if isinstance(obj, tuple):  # grid
                headers, rows = obj
                obs = grid_obs([str(h) for h in headers], rows, fgeos, fmetric)
            else:
                for pt, val in flatten_json(obj):
                    o = leaf_to_obs(pt, val, fgeos, fmetric)
                    if o:
                        obs.append(o)
        else:
            grid = parse_text_grid(text, fwords)
            if grid is None:
                # maybe JSON-ish anyway, or a simple two-column time series
                obj = parse_json_text(text)
                if obj is not None and isinstance(obj, dict):
                    for pt, val in flatten_json(obj):
                        o = leaf_to_obs(pt, val, fgeos, fmetric)
                        if o:
                            obs.append(o)
                else:
                    print(f"[skip] {tag}: no tabular structure detected")
                    return tag, []
            else:
                headers, rows = grid
                obs = grid_obs([str(h) for h in headers], rows, fgeos, fmetric)
    except Exception as exc:
        print(f"[warn] {tag}: parsing failed ({exc})")
        return tag, []
    return tag, obs

