def main():
    root = os.getcwd()
    print("=" * 72)
    print("EUROPEAN ECONOMIC PERFORMANCE - STORY REPORT BUILDER")
    print(f"workspace: {root}")
    files = discover_files(root)
    print(f"[1] candidate data files found: {len(files)}")
    observations = []
    sources = []
    for path in files:
        tag, obs = parse_file(path)
        sources.append((tag, len(obs)))
        observations.extend(obs)
        print(f"    {tag}: {len(obs)} observations")
    if observations:
        dedup = {}
        for o in observations:
            key = (o[0], o[1], o[2], round(o[3], 6))
            dedup.setdefault(key, o)
        observations = sorted(dedup.values(), key=lambda o: (o[1], o[0], o[2] or -1))
        print(f"[2] unique observations after dedup: {len(observations)}")

    now = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    lines = []
    lines.append("# The State of Europe's Economy: A Data Story")
    lines.append("")
    lines.append(f"> *Generated from workspace data on {now}*")

    if not observations:
        print("[!] no numeric observations were extracted - writing fallback report")
        lines.append("")
        lines.append("## What the data shows")
        lines.append("")
        lines.append("No structured numeric time series about European economic "
                     "performance could be located in this directory by the "
                     "discovery script. Candidate files inspected:")
        if sources:
            for tag, _n in sources:
                lines.append(f"- `{tag}`")
        else:
            lines.append("- (no candidate data files found)")
        lines.append("")
        lines.append("## Next step")
        lines.append("Add a CSV/JSON dataset (countries x years or tidy records) and "
                     "re-run the report builder.")
        with open(OUT_NAME, "w", encoding="utf-8") as fh:
            fh.write("\n".join(lines) + "\n")
        print(f"[done] report written: {OUT_NAME}")
        return

    series = build_series(observations)
    coverage = metric_coverage(series)
    print("[3] per-metric coverage (metric | geos | years | obs):")
    for c in sorted(coverage, key=lambda c: -c[3]):
        print(f"    {c[0]:<16} geos={c[1]:>3} years={c[2]:>3} obs={c[3]:>4} "
              f"({c[4]}..{c[5]})")

    hero = None
    for pref in HERO_PREFERENCE:
        for metric, ngeo, nyrs, total, y0, y1 in coverage:
            if metric == pref and ngeo >= 2 and (nyrs >= 2 or total >= 4):
                hero = metric
                break
        if hero:
            break
    if hero is None and coverage:
        hero = max(coverage, key=lambda c: (c[3]))
    if hero is None:
        hero = "indicator"

    label = METRIC_LABEL.get(hero, hero.replace("_", " ").title())
    geos_map = series[hero]
    agg_data, agg_kind, agg_src = aggregate_series(geos_map)
    facts = trend_facts(agg_data)
    print(f"[4] hero metric: {hero} ({label}); aggregate source: {agg_src} ({agg_kind})")

    # ----- context coverage -----
    real_obs = [o for o in observations if o[2] is not None]
    years_all = sorted({o[2] for o in real_obs})
    geos_all = sorted({o[0] for o in observations})
    econ_geos = sorted(g for g in geos_all if g not in AGGREGATE_GEOS)
    cover_years = f"{years_all[0]}–{years_all[-1]}" if years_all else "n/a"

    lines.append("")
    lines.append("## 1. The hook — one headline")
    lines.append("")

    if facts:
        delta = facts["total"]
        direction_word = ("up" if delta > 0 else "down")
        if hero == "unemployment":
            tone = ("falling unemployment is a sign of healing labour markets"
                    if delta < 0 else "rising unemployment is the central strain")
        elif hero == "inflation":
            tone = ("price pressure is easing" if delta < 0
                    else "price pressure is building")
        elif hero == "gdp_growth":
            tone = ("the economy is expanding faster than at the start of the period"
                    if delta > 0 else "growth momentum has cooled since the start of the period")
        elif hero == "debt":
            tone = ("public balance sheets are being repaired"
                    if delta < 0 else "public debt burdens are climbing")
        elif hero == "deficit":
            tone = ("fiscal balances are improving"
                    if delta > 0 else "fiscal positions are deteriorating")
        else:
            tone = f"the indicator moved {direction_word} over the period"
        lines.append(f"Across the economies in this dataset, **{label} went "
                     f"from {fmt_val(facts['first'], hero)} in {facts['fy']} to "
                     f"{fmt_val(facts['last'], hero)} in {facts['ly']}** "
                     f"({'+' if delta >= 0 else ''}{delta:+.2f} "
                     f"{'pp' if hero in PCT_METRICS else 'units'}) — {tone}.")
    else:
        lines.append(f"The headline indicator for this dataset is **{label}**.")

    lines.append("")
    lines.append("## 2. The context — where the numbers come from")
    lines.append("")
    lines.append(f"- **Indicator focus:** {label} (plus related metrics where available).")
    lines.append(f"- **Coverage:** {len(real_obs)} observations across "
                 f"{len(econ_geos)} European economies"
                 + (f" and {len(geos_all) - len(econ_geos)} aggregate blocks"
                    if len(geos_all) > len(econ_geos) else "")
                 + f", spanning {cover_years}.")
    lines.append(f"- **Aggregate used for trend reading:** {agg_src} "
                 f"({agg_kind}).")
    lines.append(f"- **Source files parsed:** "
                 + ", ".join(f"`{t}`" for t, _n in sources if _n)
                 + ("." if sources else "none."))

    # ----- trend -----
    lines.append("")
    lines.append("## 3. The arc — trend of the headline indicator")
    lines.append("")
    if facts and len(facts["years"]) >= 2:
        worst, best = (facts["min_year"], facts["min_val"]), (facts["max_year"], facts["max_val"])
        lines.append(f"The {agg_kind} series of **{label}** moved from "
                     f"{fmt_val(facts['first'], hero)} ({facts['fy']}) to "
                     f"{fmt_val(facts['last'], hero)} ({facts['ly']}). "
                     f"The lowest point was {fmt_val(worst[1], hero)} in {worst[0]} and "
                     f"the highest was {fmt_val(best[1], hero)} in {best[0]}.")
        if facts["yoy"] is not None:
            lines.append(f"In the final year of the sample, the indicator moved "
                         f"{'+' if facts['yoy'] >= 0 else ''}{facts['yoy']:+.2f} "
                         f"year-on-year — "
                         + ("continuing the recent direction."
                            if (facts["yoy"] >= 0) == (delta >= 0)
                            else "reversing the longer-run direction, a signal worth watching."))
        # build a compact year table
        trows = []
        for y in facts["years"]:
            trows.append([y, fmt_val(facts["y"], hero)])
        lines.append("")
        lines.append(md_table(["Year", f"{label} ({agg_src})"], trows))
        # momentum across economies
        real_lv = latest_values(geos_map, hero)
        movers = [(g, y, v) for g, y, v, _a, _b in real_lv if y is not None]
        imp = 0
        for g, y, v in movers:
            if y - 1 in geos_map[g] and geos_map[g][y - 1] is not None:
                if direction_good(hero, v - geos_map[g][y - 1]):
                    imp += 1
        if imp:
            lines.append("")
            lines.append(f"In the latest year with comparable data, "
                         f"**{imp} of {len(movers)}** economies moved in the "
                         "favourable direction for this indicator.")
    else:
        lines.append("The dataset contains mostly a single-period snapshot, so the "
                     "story is comparative rather than a time arc.")

    # ----- dispersion / leaders-laggards -----
    lines.append("")
    lines.append("## 4. The divide — leaders and laggards")
    lines.append("")
    real_lv = latest_values(geos_map, hero)
    comp = [(g, y, v) for g, y, v, _a, _b in real_lv if g not in AGGREGATE_GEOS]
    comp.sort(key=lambda t: t[2], reverse=(METRIC_DIR.get(hero, "higher") == "higher"))
    if len(comp) >= 2:
        vals = [v for _, _, v in comp]
        sd = stdev(vals)
        lines.append(f"Ranking economies by their most recent {label}, the spread is "
                     f"**{fmt_val(max(vals), hero)} vs {fmt_val(min(vals), hero)}** "
                     f"(standard deviation {sd:,.2f} if sd is not None else 'n/a'). "
                     "This gap is the story underneath the aggregate: averages hide "
                     "divergence.")
        rows = []
        for g, y, v in comp:
            rows.append([g, y if y is not None else "latest",
                         fmt_val(v, hero)])
        lines.append("")
        lines.append(md_table(["Economy", "Year", f"{label} (latest)"], rows))
        if len(comp) >= 3:
            top = comp[:3]
            bot = comp[-3:]
            lines.append("")
            lines.append(f"The strongest recent readings come from "
                         + ", ".join(f"{g} ({fmt_val(v, hero)})" for g, _y, v in top)
                         + f"; the weakest from "
                         + ", ".join(f"{g} ({fmt_val(v, hero)})" for g, _y, v in bot)
                         + ".")
    else:
        lines.append("Not enough economies with recent values for a meaningful ranking.")

    # ----- related metrics table -----
    sec = []
    for metric, ngeo, nyrs, total, _y0, _y1 in coverage:
        if metric == hero:
            continue
        if ngeo >= 3:
            sec.append(metric)
    if sec:
        lines.append("")
        lines.append("## 5. The wider dashboard — related indicators")
        lines.append("")
        lines.append("The same dataset also allows a multi-indicator view. Latest "
                     "available readings per economy:")
        lines.append("")
        headers = ["Economy"] + [METRIC_LABEL.get(m, m) for m in sec]
        rows = []
        geo_choice = sorted({g for g in geos_all if g not in AGGREGATE_GEOS})
        for g in geo_choice:
            row = [g]
            for m in sec:
                lv = latest_values(series[m], m)
                hit = [v for gg, _y, v, _a, _b in lv if gg == g]
                row.append(fmt_val(hit[0], m) if hit else "n/a")
            rows.append(row)
        lines.append(md_table(headers, rows))

    # ----- cross-metric insights -----
    lines.append("")
    lines.append("## 6. What the crossovers say — correlations in the data")
    lines.append("")
    present = [c[0] for c in coverage]
    pairs = []
    for i, a in enumerate(present):
        for b in present[i + 1:]:
            if a == b:
                continue
            pa = []
            pb = []
            for g in series[a]:
                if g in series[b]:
                    va = latest_values(series[a], a)
                    vb = latest_values(series[b], b)
                    da = {gg: v for gg, _y, v, _a2, _b2 in va}
                    db = {gg: v for gg, _y, v, _a2, _b2 in vb}
                    if g in da and g in db:
                        pa.append(da[g])
                        pb.append(db[g])
            r, n = pearson(pa, pb)
            if r is not None and n >= 5:
                pairs.append((abs(r), r, n, a, b))
    pairs.sort(reverse=True)
    if pairs:
        used = set()
        shown = 0
        for _absr, r, n, a, b in pairs:
            key = frozenset((a, b))
            if key in used:
                continue
            used.add(key)
            la = METRIC_LABEL.get(a, a)
            lb = METRIC_LABEL.get(b, b)
            sense = "tend to move together" if r >= 0 else "tend to move in opposite directions"
            lines.append(f"- Across {n} economies, **{la}** and **{lb}** {sense} "
                         f"(correlation ≈ {r:+.2f}). This is an association, not proof "
                         "of causation — treat it as a pattern worth explaining.")
            shown += 1
            if shown >= 3:
                break
        if not shown:
            lines.append("No robust pairwise patterns with five or more overlapping "
                         "economies were found.")
    else:
        lines.append("No robust pairwise patterns with five or more overlapping "
                     "economies were found in this dataset.")

    # ----- key insights & implication -----
    lines.append("")
    lines.append("## 7. The insight — three things the data says")
    lines.append("")
    insights = []
    if facts and len(comp) >= 2:
        span_hi = None
        best_run = None
        for g, y, v, y0, v0 in [(g, y, v, a, b) for g, y, v, a, b in real_lv
                                if g not in AGGREGATE_GEOS and y is not None and y0 is not None]:
            if y0 != y:
                chg = v - v0
                if best_run is None or abs(chg) > abs(best_run[1]):
                    best_run = (g, chg, y0, y, v0, v)
        if best_run:
            chg = best_run[1]
            good = direction_good(hero, chg)
            insights.append(f"**The biggest single-economy move:** "
                            f"{best_run[0]} moved from {fmt_val(best_run[4], hero)} "
                            f"({best_run[2]}) to {fmt_val(best_run[5], hero)} "
                            f"({best_run[3]}), a {'+' if chg >= 0 else ''}{chg:+.2f}-point "
                            f"shift {'in the favourable direction' if good else 'to watch'}.")
    if facts and len(comp) >= 2:
        vals = [v for _, _, v in comp]
        insights.append(f"**Divergence is real:** the most recent readings for {label} "
                        f"range from {fmt_val(min(vals), hero)} to "
                        f"{fmt_val(max(vals), hero)} across {len(comp)} economies — "
                        "European performance is not a single number but a band.")
    if facts:
        insights.append(f"**Timing matters:** the {agg_kind} series bottomed at "
                        f"{fmt_val(facts['min_val'], hero)} in {facts['min_year']} and "
                        f"closed the sample at {fmt_val(facts['last'], hero)} in "
                        f"{facts['ly']} — what happened between those dates, and which "
                        "policies accompanied it, is the question for the next analysis.")
    if pairs:
        _absr, r, n, a, b = pairs[0]
        insights.append(f"**The strongest cross-link** in this dataset pairs "
                        f"**{METRIC_LABEL.get(a, a)}** with **{METRIC_LABEL.get(b, b)}** "
                        f"(r ≈ {r:+.2f}, n = {n}) — if one is part of the story, the "
                        "other is probably part of the explanation.")
    if not insights:
        insights.append("The dataset supports a snapshot comparison; a longer time "
                        "series would sharpen the causal story.")
    for ins in insights[:3]:
        lines.append(f"- {ins}")

    lines.append("")
    lines.append("## 8. The implication and next question")
    lines.append("")
    lines.append(f"European performance is **improving on balance but unevenly**: the "
                 f"aggregate {label} trend tells one story, while the country-level "
                 f"band tells another. The actionable next step for any stakeholder is "
                 f"to ask **why the leaders lead and the laggards lag** — decomposing "
                 "the gap by structure (exports, fiscal space, labour markets) before "
                 "setting targets. The numbers in this report are the evidence base "
                 "for that discussion.")
    lines.append("")
    lines.append("## 9. Call to action")
    lines.append("")
    lines.append("- **Decide** which economies define 'success' for this metric and "
                 "benchmark against them explicitly.")
    lines.append("- **Investigate** the strongest correlation found above before "
                 "assuming causation.")
    lines.append("- **Update** this report when the next year of data lands — trend "
                 "stories get stronger with each new observation.")
    lines.append("")

    lines.append("---")
    lines.append("")
    lines.append("### Method note (honesty box)")
    lines.append("")
    lines.append(f"- Values are used **as reported** in the source files; units "
                 f"(% vs levels) follow each source's own convention.")
    lines.append(f"- Series were normalised with heuristics: "
                 f"{len(observations)} observations after de-duplication; aggregate "
                 f"series are {'reported aggregates' if agg_kind == 'reported' else 'simple cross-country means'}.")
    lines.append("- Correlations are computed on latest available overlapping values "
                 "and describe association only.")
    lines.append("- Source files parsed: "
                 + "; ".join(f"`{t}` ({n} obs)" for t, n in sources if n)
                 + ".")

    report = "\n".join(lines) + "\n"
    with open(OUT_NAME, "w", encoding="utf-8") as fh:
        fh.write(report)
    print(f"[5] report written: {OUT_NAME} ({len(report)} bytes)")
    print("[6] first lines of the report:")
    for ln in report.splitlines()[:8]:
        print("   " + ln)


if __name__ == "__main__":
    main()

